<script setup lang="ts">
import { useApi, isCancelled } from "./lib/api";
import { latestRequest } from "./lib/requests";
const api = useApi("/messages");
const loadRequest = latestRequest();
import { computed, nextTick, ref, reactive, onMounted, onUnmounted, watch } from 'vue';
import { Mail, Send, CheckCheck, Plus, ArrowLeft, Trash2, X, Inbox as InboxIcon } from 'lucide-vue-next';
import PageHeading from './components/PageHeading.vue';
import EmptyState from './components/EmptyState.vue';
import {useModalFocus} from './composables/useModalFocus';
import { t, locale } from './i18n';
type Message={id:number;sender:string;title:string;body:string;category:string;created:number;read_at:number;recipients:number;read_count:number};
const props=defineProps<{owner:boolean;users:{id:number;username:string}[];me:number;supportEmail:string;unread:number}>();
const emit=defineEmits<{refresh:[]}>();
const items=ref<Message[]>([]),folder=ref('inbox'),unreadOnly=ref(false),selected=ref<Message|null>(null),next=ref(0),busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),compose=ref(false),confirmSend=ref(false);
const search=ref(''),composeDialog=ref<HTMLElement|null>(null),messageDetail=ref<HTMLElement|null>(null),searchInput=ref<HTMLInputElement|null>(null);
let messageTrigger:HTMLElement|null=null;
const visibleMessages=computed(()=>items.value.filter(m=>[m.title,m.body,m.sender].join(' ').toLowerCase().includes(search.value.trim().toLowerCase())));
function closeCompose(){if(!busy.value){compose.value=false;confirmSend.value=false;if(draft.title||draft.body)notice.value='未发送内容已保留，重新打开即可继续编辑。';}}
useModalFocus(compose,composeDialog,closeCompose);
const draft=reactive({recipient:'',title:'',body:'',category:'notice'});
const category=(v:string)=>t(({notice:'通知',maintenance:'维护',account:'账户'} as Record<string,string>)[v]||v);
const date=(v:number)=>new Date(v*1000).toLocaleString(locale.value);
async function load(more=false){
 const request=loadRequest.start();loading.value=true;error.value='';
 try{const v=await api('?folder='+folder.value+(folder.value==='inbox'&&unreadOnly.value?'&unread=1':'')+(more?'&before='+next.value:''),'GET',undefined,{signal:request.signal});if(!loadRequest.isCurrent(request))return;items.value=more?[...items.value,...v.items]:v.items;next.value=v.next_before;}
 catch(e){if(loadRequest.isCurrent(request)&&!isCancelled(e))error.value=(e as Error).message;}
 finally{if(loadRequest.isCurrent(request))loading.value=false;}
}
onUnmounted(()=>loadRequest.cancel());
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();emit('refresh');}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
async function open(m:Message,event:MouseEvent){if(busy.value)return;messageTrigger=event.currentTarget as HTMLElement;selected.value=m;await nextTick();messageDetail.value?.focus({preventScroll:true});if(folder.value!=='sent'&&!m.read_at)await action(async()=>{await api('/'+m.id+'/read','POST',{});m.read_at=Math.floor(Date.now()/1000);});}
async function returnToList(){selected.value=null;await nextTick();if(messageTrigger?.isConnected)messageTrigger.focus({preventScroll:true});else searchInput.value?.focus({preventScroll:true});}
async function markAll(){await action(async()=>{await api('/read-all','POST',{});await load();notice.value='已全部标为已读';});}
async function remove(){if(!selected.value)return;const id=selected.value.id;await action(async()=>{await api('/'+id,'DELETE',{});selected.value=null;await load();notice.value='站内信已移除';});}
function newMessage(){if(busy.value)return;if(!draft.title&&!draft.body)Object.assign(draft,{recipient:String(props.me),title:'',body:'',category:'notice'});compose.value=true;confirmSend.value=false;error.value='';}
async function send(){await action(async()=>{await api('','POST',{title:draft.title,body:draft.body,category:draft.category,all:draft.recipient==='all',recipient_id:draft.recipient==='all'?0:Number(draft.recipient)});compose.value=false;confirmSend.value=false;selected.value=null;folder.value='sent';await load();notice.value='站内信已发送';Object.assign(draft,{recipient:String(props.me),title:'',body:'',category:'notice'});});}
watch([folder,unreadOnly],()=>{selected.value=null;items.value=[];next.value=0;search.value='';load();});watch(()=>props.unread,()=>{if(!selected.value&&!compose.value)load();});onMounted(()=>load());
</script>
<template><section class="inbox-page">
 <PageHeading :title="t('消息中心')" :description="t('维护通知、账户消息与公告，集中阅读和处理。')" eyebrow="MESSAGE CENTER"><template #actions><button v-if="owner" class="primary" :disabled="busy" @click="newMessage"><Plus :size="16"/>{{t('发送站内信')}}</button></template></PageHeading>
 <p v-if="error" class="error" role="alert">{{t(error)}}</p><p v-if="notice" class="settings-saved" role="status">{{t(notice)}}</p>
 <div class="inbox-toolbar"><div class="segmented"><button :class="{selected:folder==='inbox'}" :aria-pressed="folder==='inbox'" :disabled="busy" @click="folder='inbox'"><InboxIcon :size="15"/>{{t('收件箱')}}<span v-if="unread" class="count">{{unread}}</span></button><button v-if="owner" :class="{selected:folder==='sent'}" :aria-pressed="folder==='sent'" :disabled="busy" @click="folder='sent'"><Send :size="15"/>{{t('已发送')}}</button></div><span class="spacer"/><label v-if="folder==='inbox'" class="inline-check"><input v-model="unreadOnly" :disabled="busy" type="checkbox"/>{{t('仅看未读')}}</label><button v-if="folder==='inbox'" :disabled="busy||!unread" @click="markAll"><CheckCheck :size="15"/>{{t('全部已读')}}</button></div>
 <div class="inbox-workspace" :class="{'has-selection':!!selected}"><aside class="inbox-directory"><label class="inbox-search"><span class="sr-only">{{t('搜索已加载的消息')}}</span><input ref="searchInput" v-model="search" type="search" :placeholder="t('搜索已加载的消息')"/></label><div class="message-list" :aria-busy="loading"><button v-for="m in visibleMessages" :key="m.id" :class="['message-row',{unread:folder==='inbox'&&!m.read_at,active:selected?.id===m.id}]" :disabled="busy" :aria-current="selected?.id===m.id?'true':undefined" @click="open(m,$event)"><span class="message-symbol"><Mail :size="18"/><i v-if="folder==='inbox'&&!m.read_at"/></span><div class="message-preview"><div><strong>{{m.title}}</strong><span class="badge neutral">{{category(m.category)}}</span></div><p>{{m.body}}</p><small>{{m.sender}}<span v-if="folder==='sent'"> · {{t('已读')}} {{m.read_count}} / {{m.recipients}}</span></small></div><time>{{date(m.created)}}</time></button><EmptyState v-if="!visibleMessages.length" :title="t(loading?'正在加载…':search?'没有匹配的消息':'暂无站内信')" :description="t(search?'试试其他标题、发送人或关键词。':unreadOnly?'你已读完全部消息':'维护通知与账户消息会显示在这里')"><template #icon><InboxIcon :size="28"/></template><template v-if="search" #actions><button @click="search=''">{{t('清除筛选')}}</button></template></EmptyState><button v-if="next" class="load-more" :disabled="loading" @click="load(true)">{{t('加载更多')}}</button></div></aside><div class="inbox-reader"><article v-if="selected" ref="messageDetail" tabindex="-1" class="message-detail"><header><button class="text-button" @click="returnToList"><ArrowLeft :size="16"/>{{t('返回列表')}}</button><button v-if="folder==='inbox'" class="text-button" :disabled="busy" @click="remove"><Trash2 :size="15"/>{{t('移出收件箱')}}</button></header><span class="badge neutral">{{category(selected.category)}}</span><h2>{{selected.title}}</h2><p class="message-meta">{{selected.sender}} · {{date(selected.created)}}<span v-if="folder==='sent'"> · {{t('已读')}} {{selected.read_count}} / {{selected.recipients}}</span></p><div class="message-body">{{selected.body}}</div></article><EmptyState v-if="!selected" :title="t('选择一条消息开始阅读')" :description="t('未读通知已在列表中标记，打开后自动标为已读。')"><template #icon><Mail :size="30"/></template></EmptyState></div></div>
 <p class="message-support" v-if="supportEmail">{{t('需要帮助？')}} <a :href="'mailto:'+supportEmail">{{supportEmail}}</a></p>
 <Teleport to="body"><div v-if="compose" class="message-overlay" @click.self="closeCompose"><form ref="composeDialog" tabindex="-1" class="compose-card inbox-compose" role="dialog" aria-modal="true" :aria-label="t('发送站内信')" @submit.prevent="confirmSend=true"><header><div><span class="eyebrow">NEW MESSAGE</span><h2>{{t('发送站内信')}}</h2></div><button class="icon" type="button" :aria-label="t('关闭')" @click="closeCompose" :disabled="busy"><X :size="20"/></button></header><p v-if="error" class="error" role="alert">{{t(error)}}</p><div class="settings-fields"><label>{{t('收件人')}}<select :disabled="busy" v-model="draft.recipient" required :aria-label="t('收件人')"><option value="all">{{t('全部现有成员')}}</option><option v-for="u in users" :key="u.id" :value="String(u.id)">{{u.username}}</option></select></label><label>{{t('消息类型')}}<select :disabled="busy" v-model="draft.category"><option value="notice">{{t('通知')}}</option><option value="maintenance">{{t('维护')}}</option><option value="account">{{t('账户')}}</option></select></label></div><label>{{t('标题')}}<input :disabled="busy" v-model="draft.title" required maxlength="120" :aria-label="t('标题')"/></label><label>{{t('正文')}}<textarea :disabled="busy" v-model="draft.body" required rows="7" maxlength="8000" :aria-label="t('正文')"/></label><small>{{draft.body.length}} / 8000 · {{t('仅支持纯文本')}}</small><div v-if="confirmSend" class="send-confirm"><p>{{t('确认发送给')}} <strong>{{draft.recipient==='all'?t('全部现有成员'):users.find(u=>String(u.id)===draft.recipient)?.username}}</strong>？</p><button type="button" class="primary" :disabled="busy" @click="send">{{t(busy?'发送中…':'确认发送')}}</button><button type="button" @click="confirmSend=false" :disabled="busy">{{t('继续编辑')}}</button></div><footer v-else><button type="button" @click="closeCompose" :disabled="busy">{{t('取消')}}</button><button class="primary"><Send :size="15"/>{{t('预览收件人并发送')}}</button></footer></form></div></Teleport>
</section></template>

<style scoped>
.inbox-page{display:grid;gap:22px;min-width:0}.inbox-toolbar{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin:0}.inbox-toolbar .segmented{display:flex;gap:4px;background:var(--surface-raised);border:1px solid var(--border);padding:4px;border-radius:10px}.inbox-toolbar .segmented button{min-height:44px;border:0;background:none;color:var(--secondary);padding:10px 14px}.inbox-toolbar .segmented button.selected{background:var(--surface);color:var(--accent);box-shadow:var(--shadow-card)}.inbox-toolbar>.inline-check{font-size:13px;min-height:44px}.inbox-toolbar>button{min-height:44px;font-size:13px}.inbox-workspace{display:grid;grid-template-columns:minmax(300px,.8fr) minmax(0,1.2fr);border:1px solid var(--border);border-radius:12px;background:var(--surface);overflow:hidden;min-height:480px}.inbox-directory{border-right:1px solid var(--border);min-width:0}.inbox-search{display:block;padding:16px;border-bottom:1px solid var(--border)}.inbox-search input{width:100%;min-height:44px;font-size:13px}.message-list{display:block;max-height:650px;overflow:auto}.message-row{display:flex;width:100%;align-items:flex-start;gap:12px;text-align:left;padding:18px 16px;border:0;border-bottom:1px solid var(--border);border-radius:0;background:var(--surface);white-space:normal;position:relative;flex-wrap:wrap}.message-row:hover{background:var(--surface-hover)}.message-row.active{background:var(--accent-soft);box-shadow:inset 3px 0 var(--accent)}.message-row.unread .message-preview strong{font-weight:700}.message-symbol{display:grid;place-items:center;width:36px;height:36px;flex:0 0 36px;border-radius:10px;background:var(--surface-raised);color:var(--secondary);position:relative}.message-symbol i{position:absolute;right:0;top:0;width:7px;height:7px;border-radius:50%;background:var(--accent);border:2px solid var(--surface)}.message-preview{min-width:0;flex:1}.message-preview>div{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.message-preview strong{font-size:14px;line-height:1.6;font-weight:500;overflow-wrap:anywhere}.message-preview .badge{font-size:12px}.message-preview p{font-size:13px;line-height:1.7;color:var(--secondary);margin:5px 0 8px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;white-space:normal}.message-preview small{font-size:12px;color:var(--muted)}.message-row time{flex-basis:100%;padding-left:48px;font-size:12px;color:var(--muted);margin:0}.load-more{margin:15px auto;display:flex;min-height:44px}.inbox-reader{min-width:0;display:flex;align-items:stretch}.inbox-reader>.ui-empty-state{width:100%;margin:auto}.message-detail{padding:26px;border:0;border-radius:0;background:none;width:100%;min-width:0}.message-detail>header{display:flex;align-items:center;justify-content:space-between;gap:14px;border-bottom:1px solid var(--border);padding:0 0 17px;margin-bottom:24px}.message-detail header button{min-height:44px;font-size:12px}.message-detail h2{font-size:23px;line-height:1.6;margin:14px 0 10px;overflow-wrap:anywhere}.message-meta{font-size:12px;color:var(--muted);line-height:1.8;margin:0 0 24px}.message-body{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9;font-size:14px;color:var(--text)}.message-support{font-size:13px;color:var(--secondary);margin:0;line-height:1.7}.message-support a{color:var(--accent)}.inbox-compose{max-height:92dvh;overflow:auto}.inbox-compose textarea{resize:vertical;min-height:150px}.inbox-compose>small{font-size:12px;color:var(--muted)}.inbox-compose .send-confirm{padding:18px;background:var(--accent-soft);border:1px solid var(--border);border-radius:10px}.inbox-compose .send-confirm p{font-size:14px;line-height:1.7}.inbox-compose .send-confirm button{margin:6px 8px 0 0;min-height:44px}.inbox-compose footer button{min-height:44px}@media(max-width:850px){.inbox-workspace{grid-template-columns:1fr;min-height:320px}.inbox-directory{border-right:0}.inbox-workspace:not(.has-selection) .inbox-reader{display:none}.inbox-workspace.has-selection .inbox-directory{display:none}.message-list{max-height:none}.message-detail{padding:20px}.message-detail h2{font-size:21px}.inbox-toolbar{gap:10px}.inbox-toolbar .spacer{display:none}.inbox-toolbar .segmented{flex-basis:100%}.inbox-toolbar .segmented button{flex:1}.inbox-toolbar>.inline-check{margin-right:auto}.message-row{padding:18px}.inbox-compose .settings-fields{grid-template-columns:1fr}.message-detail>header{flex-wrap:wrap;gap:8px}.message-detail header button{padding:8px 0}}
</style>
